fn fibonacci(n: usize) -> Vec<i32> {
    // Pre-allocate a vector with capacity `n`
    let mut fib = Vec::with_capacity(n);

    // According to problem, n >= 2, so safe to initialize first two elements
    fib.push(0);
    fib.push(1);

    // Calculate Fibonacci numbers for indices 2 to n-1
    for i in 2..n {
        // Safe to unwrap since i-1 and i-2 are guaranteed valid indices
        let next = fib[i - 1] + fib[i - 2];
        fib.push(next);
    }

    fib
}